다음 코드의 문제는 무엇인가?

```js
function Counter() {
  const countRef = useRef(0);
  function handleClick() { countRef.current++; }
  return <button onClick={handleClick}>You clicked {countRef.current} times</button>;
}
```

다음 코드는 모든 인스턴스가 같은 timeout을 공유해 디바운싱이 충돌한다. 인스턴스별 격리를 회복하도록 useRef로 리팩터링한 코드를 작성하시오.

```js
let timeoutID;
function DebouncedButton({ onClick, children }) {
  return (
    <button onClick={() => {
      clearTimeout(timeoutID);
      timeoutID = setTimeout(onClick, 1000);
    }}>{children}</button>
  );
}
```

다음 코드 조각에서 안티패턴을 가장 정확하게 지적한 것은?

```js
function ThemedView({ children }) {
  const modeRef = useRef('light');
  if (modeRef.current === 'dark') return <DarkLayout>{children}</DarkLayout>;
  return <LightLayout>{children}</LightLayout>;
}
```
